package GeneratedModel {
  private import ScalarValues::*;
  part def Controller {
    in attribute io_0 : Boolean;
    attribute previousPressed : Boolean := false;
    perform action tick {
      first start;
      then if io_0 and not previousPressed {
        first start;
        then assign previousPressed := true;
      } else {
        first start;
        then assign previousPressed := false;
      }
    }
    out attribute io_1 : Boolean = (if io_0 ? true else false);
    out attribute io_2 : Boolean = (if io_0 ? false else true);
    out attribute serial_0_trigger : Boolean = io_0;
    out attribute serial_0_value_0 : Boolean = io_0;
  }
  part system : Controller;
}
